#include <bits/stdc++.h>
using namespace std;

constexpr int MOD = 1000000007;

int count_matchings(const vector<vector<int>>& allowed) {
    int n = static_cast<int>(allowed.size());
    int states = 1 << n;
    vector<int> used(states), ways(states);
    for (int mask = 1; mask < states; ++mask) {
        used[mask] = used[mask >> 1] + (mask & 1);
    }

ways[0] = 1;
for (int mask = 0; mask < states; ++mask) {
    int person = used[mask];
    if (person == n || ways[mask] == 0) {
        continue;
    }
    for (int option = 0; option < n; ++option) {
        if ((mask & (1 << option)) == 0 && allowed[person][option]) {
            int& next = ways[mask | (1 << option)];
            next += ways[mask];
            if (next >= MOD) {
                next -= MOD;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> allowed(n, vector<int>(n));
    for (auto& row : allowed) {
        for (int& value : row) {
            cin >> value;
        }
    }
    cout << count_matchings(allowed) << '\n';
}

